import { Bell } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { NotificationsDrawer } from '@/components/notifications/notifications-drawer';
import { SidebarUnreadBadge } from '@/components/sidebar-unread-badge';
import {
    SidebarMenu,
    SidebarMenuButton,
    SidebarMenuItem,
} from '@/components/ui/sidebar';
import { announce } from '@/lib/live-announcer';
import {
    attachNotificationSoundUnlockListeners,
    getNotificationSoundPreferences,
    playNotificationSound,
    setNotificationSoundPreferences,
    unlockNotificationSound,
} from '@/lib/notification-sound';
import { NOTIFICATIONS_UPDATED_EVENT } from '@/lib/notifications-api';
import type { NotificationsSource } from '@/lib/notifications-api';

const UNREAD_ANNOUNCE_DEBOUNCE_MS = 800;

type NotificationsBellProps = {
    /** The server calls (`createNotificationsSource(...)` for the Laravel contract). */
    source: NotificationsSource;
    /**
     * The unread count from the shared Inertia prop. Every visit refreshes it,
     * so without realtime the badge updates on navigation.
     */
    unreadCount: number;
    /**
     * Optional realtime: subscribes to "a notification was created" for the
     * signed-in user and returns the unsubscribe. Pass a stable function
     * (`useCallback`). Without it, there are no live updates.
     */
    subscribe?: (onNotificationCreated: () => void) => () => void;
    /** The user's sound preference; off by default. */
    isSoundEnabled?: boolean;
};

/**
 * Sidebar bell with the unread badge, opening the notifications drawer on the
 * right. Unread rises are announced politely to screen readers (debounced, so a
 * burst is one announcement) and, with the sound preference on and the drawer
 * closed, a live notification chimes.
 */
export function NotificationsBell({
    source,
    unreadCount: sharedUnreadCount,
    subscribe,
    isSoundEnabled = false,
}: NotificationsBellProps) {
    const { t } = useTranslation();
    const [unreadCount, setUnreadCount] = useState(sharedUnreadCount);
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [reloadToken, setReloadToken] = useState(0);
    const isDrawerOpenRef = useRef(isDrawerOpen);
    const previousUnreadCountRef = useRef(sharedUnreadCount);
    const announceTimeoutRef = useRef<number | undefined>(undefined);

    useEffect(() => {
        isDrawerOpenRef.current = isDrawerOpen;
    }, [isDrawerOpen]);

    const [previousSharedUnreadCount, setPreviousSharedUnreadCount] =
        useState(sharedUnreadCount);

    // Adopt a new server count during render (React's "adjust state on prop change" pattern).
    if (previousSharedUnreadCount !== sharedUnreadCount) {
        setPreviousSharedUnreadCount(sharedUnreadCount);
        setUnreadCount(sharedUnreadCount);
    }

    const refreshUnreadCount = useCallback(() => {
        void source
            .fetchUnreadCount()
            .then(setUnreadCount)
            .catch(() => {
                // The next visit or event brings the count back.
            });
    }, [source]);

    useEffect(() => {
        const previousCount = previousUnreadCountRef.current;
        previousUnreadCountRef.current = unreadCount;

        if (unreadCount <= previousCount || isDrawerOpenRef.current) {
            return;
        }

        if (announceTimeoutRef.current) {
            window.clearTimeout(announceTimeoutRef.current);
        }

        // Debounce realtime bursts so VoiceOver hears one polite update.
        announceTimeoutRef.current = window.setTimeout(() => {
            announce(t('a11y.notificationsUnread', { count: unreadCount }), {
                politeness: 'polite',
            });
        }, UNREAD_ANNOUNCE_DEBOUNCE_MS);

        return () => {
            if (announceTimeoutRef.current) {
                window.clearTimeout(announceTimeoutRef.current);
            }
        };
    }, [unreadCount, t]);

    useEffect(() => {
        window.addEventListener(
            NOTIFICATIONS_UPDATED_EVENT,
            refreshUnreadCount,
        );

        const unsubscribe = subscribe?.(() => {
            refreshUnreadCount();
            setReloadToken((token) => token + 1);

            if (!isDrawerOpenRef.current) {
                playNotificationSound();
            }
        });

        return () => {
            window.removeEventListener(
                NOTIFICATIONS_UPDATED_EVENT,
                refreshUnreadCount,
            );
            unsubscribe?.();
        };
    }, [subscribe, refreshUnreadCount]);

    useEffect(() => {
        setNotificationSoundPreferences({
            ...getNotificationSoundPreferences(),
            isNotificationSoundEnabled: isSoundEnabled,
        });

        if (!isSoundEnabled) {
            return;
        }

        // Turning the preference on is a gesture opportunity: unlock early.
        unlockNotificationSound();

        return attachNotificationSoundUnlockListeners();
    }, [isSoundEnabled]);

    const handleUnreadCountChange = useCallback((count: number) => {
        setUnreadCount(count);
    }, []);

    const notificationsLabel =
        unreadCount > 0
            ? t('a11y.notificationsUnread', { count: unreadCount })
            : t('a11y.notifications');

    return (
        <>
            <SidebarMenu>
                <SidebarMenuItem>
                    <SidebarMenuButton
                        type="button"
                        tooltip={{ children: t('a11y.notifications') }}
                        onClick={() => setIsDrawerOpen(true)}
                        data-test="notifications-bell"
                        aria-label={notificationsLabel}
                        aria-expanded={isDrawerOpen}
                        aria-haspopup="dialog"
                    >
                        <Bell aria-hidden="true" />
                        <span>{t('a11y.notifications')}</span>
                    </SidebarMenuButton>
                    <SidebarUnreadBadge count={unreadCount} decorative />
                </SidebarMenuItem>
            </SidebarMenu>

            <NotificationsDrawer
                open={isDrawerOpen}
                onOpenChange={setIsDrawerOpen}
                source={source}
                onUnreadCountChange={handleUnreadCountChange}
                reloadToken={reloadToken}
            />
        </>
    );
}

import { Link } from '@inertiajs/react';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '@/components/ui/button';
import {
    Item,
    ItemContent,
    ItemDescription,
    ItemFooter,
    ItemGroup,
    ItemMedia,
    ItemTitle,
} from '@/components/ui/item';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
    Sheet,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetTitle,
} from '@/components/ui/sheet';
import { Spinner } from '@/components/ui/spinner';
import { notifyNotificationsUpdated } from '@/lib/notifications-api';
import type {
    NotificationItem,
    NotificationsSource,
} from '@/lib/notifications-api';
import { toast } from '@/lib/toast';
import { cn } from '@/lib/utils';

type NotificationsDrawerProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    source: NotificationsSource;
    onUnreadCountChange: (count: number) => void;
    /** Bumped by the bell when a notification arrives live, to reload the open list. */
    reloadToken?: number;
};

/** The whole row is the link: its `::after` covers the item, actions sit above it. */
const STRETCHED_LINK_CLASS =
    'after:absolute after:inset-0 after:rounded-md focus-visible:outline-none';

/**
 * Right-side drawer listing the user's notifications, newest first. Clicking
 * one marks it read and opens its link; each has "Mark as read" (or "Mark as
 * unread" when the source supports it), and the header has "Mark all as read".
 *
 * ponytail: only the first page (the backend's 20 newest); add "Load more"
 * when people need older notifications here.
 */
export function NotificationsDrawer({
    open,
    onOpenChange,
    source,
    onUnreadCountChange,
    reloadToken = 0,
}: NotificationsDrawerProps) {
    const { t, i18n } = useTranslation();
    const [notifications, setNotifications] = useState<NotificationItem[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [hasLoadFailed, setHasLoadFailed] = useState(false);
    const [isMutating, setIsMutating] = useState(false);

    const hasUnread = notifications.some(
        (notification) => !notification.isRead,
    );

    useEffect(() => {
        if (!open) {
            return;
        }

        let isCancelled = false;

        const load = async (): Promise<void> => {
            setIsLoading(true);
            setHasLoadFailed(false);

            try {
                const items = await source.fetchNotifications();

                if (!isCancelled) {
                    setNotifications(items);
                }
            } catch {
                if (!isCancelled) {
                    setHasLoadFailed(true);
                }
            } finally {
                if (!isCancelled) {
                    setIsLoading(false);
                }
            }
        };

        void load();

        return () => {
            isCancelled = true;
        };
    }, [open, source, reloadToken]);

    /**
     * Runs a read-state change, applies it to the list and reports the server's
     * new unread count; a failure leaves the list as it was and says so.
     */
    const mutate = async (
        request: () => Promise<number>,
        applyToList: (current: NotificationItem[]) => NotificationItem[],
    ): Promise<void> => {
        setIsMutating(true);

        try {
            const unreadCount = await request();
            setNotifications(applyToList);
            onUnreadCountChange(unreadCount);
            notifyNotificationsUpdated();
        } catch {
            toast.error(t('notifications.updateFailed'));
        } finally {
            setIsMutating(false);
        }
    };

    const setReadState =
        (ids: string[] | 'all', isRead: boolean) =>
        (current: NotificationItem[]) =>
            current.map((notification) =>
                ids === 'all' || ids.includes(notification.id)
                    ? { ...notification, isRead }
                    : notification,
            );

    const handleMarkAllRead = (): void => {
        if (isMutating || !hasUnread) {
            return;
        }

        void mutate(() => source.markRead('all'), setReadState('all', true));
    };

    const handleMarkRead = (id: string): void => {
        void mutate(() => source.markRead([id]), setReadState([id], true));
    };

    const handleMarkUnread = (id: string): void => {
        const { markUnread } = source;

        if (!markUnread) {
            return;
        }

        void mutate(() => markUnread([id]), setReadState([id], false));
    };

    /** The click navigates at once; the read request finishes in the background. */
    const handleOpen = (notification: NotificationItem): void => {
        if (!notification.isRead) {
            handleMarkRead(notification.id);
        }

        onOpenChange(false);
    };

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent side="right" className="w-full sm:max-w-md">
                <SheetHeader>
                    <SheetTitle>{t('notifications.title')}</SheetTitle>
                    <SheetDescription>
                        {t('notifications.description')}
                    </SheetDescription>
                </SheetHeader>

                <div className="flex items-center justify-end px-4 pb-2">
                    <Button
                        type="button"
                        variant="ghost"
                        className="text-muted-foreground hover:text-foreground"
                        disabled={isMutating || isLoading || !hasUnread}
                        onClick={handleMarkAllRead}
                        data-test="notifications-mark-all-read"
                    >
                        {t('notifications.markAllRead')}
                    </Button>
                </div>

                <ScrollArea className="min-h-0 flex-1">
                    <ItemGroup className="gap-2 px-4 pb-4">
                        {isLoading ? (
                            <div className="flex flex-col items-center gap-2 py-6 text-sm text-muted-foreground">
                                <Spinner className="size-5" />
                                {t('notifications.loading')}
                            </div>
                        ) : null}

                        {!isLoading && hasLoadFailed ? (
                            <p className="text-sm text-muted-foreground">
                                {t('notifications.loadFailed')}
                            </p>
                        ) : null}

                        {!isLoading &&
                        !hasLoadFailed &&
                        notifications.length === 0 ? (
                            <p className="text-sm text-muted-foreground">
                                {t('notifications.empty')}
                            </p>
                        ) : null}

                        {notifications.map((notification) => {
                            const Icon = notification.icon;
                            const title =
                                notification.title ||
                                t('notifications.untitled');
                            const isUnread = !notification.isRead;

                            return (
                                <Item
                                    key={notification.id}
                                    role="listitem"
                                    variant="outline"
                                    size="sm"
                                    className={cn(
                                        'relative gap-x-3 gap-y-1 p-3 has-[a:focus-visible]:border-ring has-[a:focus-visible]:ring-[3px] has-[a:focus-visible]:ring-ring/50',
                                        notification.link &&
                                            'hover:bg-accent/50',
                                        isUnread && 'bg-muted/40',
                                    )}
                                    data-unread={isUnread || undefined}
                                    data-test="notifications-item"
                                >
                                    {Icon ? (
                                        <ItemMedia variant="icon">
                                            <Icon aria-hidden="true" />
                                        </ItemMedia>
                                    ) : null}
                                    <ItemContent>
                                        <ItemTitle>
                                            {notification.link ? (
                                                notification.isDocumentLink ? (
                                                    <a
                                                        href={notification.link}
                                                        className={
                                                            STRETCHED_LINK_CLASS
                                                        }
                                                        onClick={() =>
                                                            handleOpen(
                                                                notification,
                                                            )
                                                        }
                                                    >
                                                        {title}
                                                    </a>
                                                ) : (
                                                    <Link
                                                        href={notification.link}
                                                        className={
                                                            STRETCHED_LINK_CLASS
                                                        }
                                                        onClick={() =>
                                                            handleOpen(
                                                                notification,
                                                            )
                                                        }
                                                    >
                                                        {title}
                                                    </Link>
                                                )
                                            ) : (
                                                title
                                            )}
                                        </ItemTitle>
                                        {notification.body ? (
                                            <ItemDescription className="line-clamp-none">
                                                {notification.body}
                                            </ItemDescription>
                                        ) : null}
                                        <time
                                            dateTime={notification.time}
                                            className="mt-1 text-xs text-muted-foreground"
                                        >
                                            {new Date(
                                                notification.time,
                                            ).toLocaleString(i18n.language)}
                                        </time>
                                    </ItemContent>
                                    <ItemFooter className="relative z-10 flex-wrap justify-start gap-x-3 gap-y-1">
                                        {isUnread ? (
                                            <Button
                                                type="button"
                                                variant="link"
                                                className="h-auto px-0 text-muted-foreground hover:text-foreground"
                                                disabled={isMutating}
                                                onClick={() =>
                                                    handleMarkRead(
                                                        notification.id,
                                                    )
                                                }
                                                data-test="notifications-mark-read"
                                            >
                                                {t('notifications.markRead')}
                                            </Button>
                                        ) : null}
                                        {!isUnread && source.markUnread ? (
                                            <Button
                                                type="button"
                                                variant="link"
                                                className="h-auto px-0 text-muted-foreground hover:text-foreground"
                                                disabled={isMutating}
                                                onClick={() =>
                                                    handleMarkUnread(
                                                        notification.id,
                                                    )
                                                }
                                                data-test="notifications-mark-unread"
                                            >
                                                {t('notifications.markUnread')}
                                            </Button>
                                        ) : null}
                                    </ItemFooter>
                                </Item>
                            );
                        })}
                    </ItemGroup>
                </ScrollArea>
            </SheetContent>
        </Sheet>
    );
}

import { useTranslation } from 'react-i18next';
import { Badge } from '@/components/ui/badge';
import { SidebarMenuBadge } from '@/components/ui/sidebar';
import { cn } from '@/lib/utils';

type SidebarUnreadBadgeProps = {
    count: number;
    className?: string;
    'data-test'?: string;
    /**
     * When true, the badge is decorative (parent already announces the count).
     * Default: meaningful status with an accessible unread label.
     */
    decorative?: boolean;
};

/** The badge text: the count, capped at "99+". */
export function formatUnreadCount(count: number): string {
    if (count <= 0) {
        return '';
    }

    return count > 99 ? '99+' : String(count);
}

/**
 * Unread count pill for sidebar nav items (chat, notifications).
 * Uses shadcn SidebarMenuBadge + Badge; keep as a sibling of SidebarMenuButton.
 */
export function SidebarUnreadBadge({
    count,
    className,
    'data-test': dataTest,
    decorative = false,
}: SidebarUnreadBadgeProps) {
    const { t } = useTranslation();

    if (count <= 0) {
        return null;
    }

    return (
        <SidebarMenuBadge
            data-test={dataTest}
            className={cn(
                'top-1/2 right-2 -translate-y-1/2 p-0 group-data-[collapsible=icon]:right-1 group-data-[collapsible=icon]:flex',
                className,
            )}
            {...(decorative
                ? { 'aria-hidden': true as const }
                : {
                      role: 'status' as const,
                      'aria-label': t('a11y.unreadCount', { count }),
                  })}
        >
            <Badge
                variant="destructive"
                className="h-5 min-w-5 rounded-full px-1 text-xs leading-none font-semibold tabular-nums"
            >
                {formatUnreadCount(count)}
            </Badge>
        </SidebarMenuBadge>
    );
}

import type { ComponentType } from 'react';

/**
 * The client side of the notification centre (`docs/notifications.md`): the
 * item the drawer renders, the source the bell and drawer call, and a default
 * source for the Laravel backend contract. The app passes its own endpoint
 * URLs (strings or Wayfinder routes), so no route is hard-coded here.
 */

/** Custom event name fired when unread notification counts may have changed. */
export const NOTIFICATIONS_UPDATED_EVENT = 'notifications:updated';

/**
 * Tells the bell to re-read the unread count, for example after an action
 * elsewhere in the app created or read notifications.
 */
export function notifyNotificationsUpdated(): void {
    window.dispatchEvent(new Event(NOTIFICATIONS_UPDATED_EVENT));
}

/** A Laravel database notification row, as the backend contract returns it. */
export type DatabaseNotificationRow = {
    id: string;
    type: string;
    data: Record<string, unknown>;
    read_at: string | null;
    created_at: string;
};

/**
 * One notification as the drawer shows it. The app maps its own notification
 * types to this shape (`toItem`): which icon, which title, where it leads.
 */
export type NotificationItem = {
    id: string;
    /** A `lucide-react` icon; none shows no media column. */
    icon?: ComponentType<{ className?: string }>;
    title: string;
    body?: string;
    /** Where clicking the notification goes; none makes it plain text. */
    link?: string | null;
    /** Open the link with a full page load (a download, a non-Inertia URL). */
    isDocumentLink?: boolean;
    /** ISO 8601 creation time. */
    time: string;
    isRead: boolean;
};

/** Everything the bell and the drawer need from the server. */
export type NotificationsSource = {
    /** The newest notifications (the first page). */
    fetchNotifications: () => Promise<NotificationItem[]>;
    fetchUnreadCount: () => Promise<number>;
    /** Marks the ids, or every notification, read; resolves to the new unread count. */
    markRead: (ids: string[] | 'all') => Promise<number>;
    /** Marks the ids unread; without it the drawer offers no "Mark as unread". */
    markUnread?: (ids: string[]) => Promise<number>;
};

/** A URL string or a Wayfinder route (`{ url, method }`). */
type EndpointUrl = string | { url: string };

/** The app's notification routes (externa-core: `/notifications`, …). */
export type NotificationsEndpoints = {
    index: EndpointUrl;
    unreadCount: EndpointUrl;
    read: EndpointUrl;
    unread?: EndpointUrl;
};

function endpointUrl(endpoint: EndpointUrl): string {
    return typeof endpoint === 'string' ? endpoint : endpoint.url;
}

/**
 * Laravel accepts the `XSRF-TOKEN` cookie back as `X-XSRF-TOKEN`; the
 * `csrf-token` meta tag is the fallback for apps without the cookie.
 */
function csrfHeaders(): Record<string, string> {
    const cookieMatch = document.cookie.match(/(?:^|;\s*)XSRF-TOKEN=([^;]+)/);

    if (cookieMatch) {
        return { 'X-XSRF-TOKEN': decodeURIComponent(cookieMatch[1]) };
    }

    const metaToken = document
        .querySelector('meta[name="csrf-token"]')
        ?.getAttribute('content');

    return metaToken ? { 'X-CSRF-TOKEN': metaToken } : {};
}

/**
 * Same-origin JSON request.
 *
 * @throws {Error} When the response is not 2xx
 */
async function requestJson<ResponseBody>(
    url: string,
    body?: unknown,
): Promise<ResponseBody> {
    const response = await fetch(url, {
        method: body === undefined ? 'GET' : 'POST',
        credentials: 'same-origin',
        // A click on a notification marks it read and navigates at once.
        keepalive: body !== undefined,
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            ...csrfHeaders(),
        },
        body: body === undefined ? undefined : JSON.stringify(body),
    });

    if (!response.ok) {
        throw new Error(`${url} answered ${response.status}`);
    }

    return (await response.json()) as ResponseBody;
}

/**
 * The default mapping: `data.title`, `data.body` and `data.url` of the
 * notification's `toArray()`, no icon. Apps with typed notifications pass
 * their own `toItem` to pick icons and build links.
 */
export function defaultNotificationItem(
    row: DatabaseNotificationRow,
): NotificationItem {
    const { title, body, url } = row.data;

    return {
        id: row.id,
        title: typeof title === 'string' ? title : '',
        body: typeof body === 'string' ? body : undefined,
        link: typeof url === 'string' ? url : null,
        time: row.created_at,
        isRead: row.read_at !== null,
    };
}

/**
 * A {@link NotificationsSource} for the Laravel backend contract: `GET index`
 * (paginated `{ data: rows }`), `GET unreadCount` (`{ count }`), `POST read`
 * (`{ ids }` or `{ all: true }`) and `POST unread` (`{ ids }`), both answering
 * `{ unread_count }`.
 */
export function createNotificationsSource(
    endpoints: NotificationsEndpoints,
    toItem: (
        row: DatabaseNotificationRow,
    ) => NotificationItem = defaultNotificationItem,
): NotificationsSource {
    const unreadEndpoint = endpoints.unread;

    return {
        fetchNotifications: async () => {
            const payload = await requestJson<{
                data: DatabaseNotificationRow[];
            }>(endpointUrl(endpoints.index));

            return payload.data.map(toItem);
        },
        fetchUnreadCount: async () => {
            const payload = await requestJson<{ count: number }>(
                endpointUrl(endpoints.unreadCount),
            );

            return payload.count;
        },
        markRead: async (ids) => {
            const payload = await requestJson<{ unread_count: number }>(
                endpointUrl(endpoints.read),
                ids === 'all' ? { all: true } : { ids },
            );

            return payload.unread_count;
        },
        markUnread: unreadEndpoint
            ? async (ids) => {
                  const payload = await requestJson<{ unread_count: number }>(
                      endpointUrl(unreadEndpoint),
                      { ids },
                  );

                  return payload.unread_count;
              }
            : undefined,
    };
}

/**
 * Notification and chat sounds, synthesised with the Web Audio API (no audio
 * files to ship). Both are **off by default**: the app turns them on from the
 * user's preference with `setNotificationSoundPreferences()`.
 *
 * A sound plays only when its preference is on, the tab is visible, and the
 * browser has unlocked audio after a user gesture (autoplay policy).
 */

/** The user's sound preferences; both default to off. */
export type NotificationSoundPreferences = {
    isChatSoundEnabled: boolean;
    isNotificationSoundEnabled: boolean;
};

const DEFAULT_PREFERENCES: NotificationSoundPreferences = {
    isChatSoundEnabled: false,
    isNotificationSoundEnabled: false,
};

let preferences: NotificationSoundPreferences = { ...DEFAULT_PREFERENCES };
let audioContext: AudioContext | null = null;
let isAudioUnlocked = false;
let hasUnlockListeners = false;

function browserWindow(): (Window & typeof globalThis) | null {
    return typeof window === 'undefined' ? null : window;
}

/**
 * Replaces the sound preferences (call it with the user's saved settings).
 */
export function setNotificationSoundPreferences(
    nextPreferences: NotificationSoundPreferences,
): void {
    preferences = { ...nextPreferences };
}

/** A copy of the current sound preferences. */
export function getNotificationSoundPreferences(): NotificationSoundPreferences {
    return { ...preferences };
}

function isVisibleTab(): boolean {
    return browserWindow()?.document.visibilityState === 'visible';
}

function ensureAudioContext(): AudioContext | null {
    const currentWindow = browserWindow();

    if (!currentWindow) {
        return null;
    }

    const AudioContextConstructor =
        currentWindow.AudioContext ??
        (
            currentWindow as typeof currentWindow & {
                webkitAudioContext?: typeof AudioContext;
            }
        ).webkitAudioContext;

    if (!AudioContextConstructor) {
        return null;
    }

    if (!audioContext) {
        audioContext = new AudioContextConstructor();
    }

    return audioContext;
}

/**
 * Resumes the audio context after a user gesture (browser autoplay policy).
 * Safe to call repeatedly: it also resumes a context the browser suspended.
 */
export function unlockNotificationSound(): void {
    const context = ensureAudioContext();

    if (!context) {
        return;
    }

    if (context.state === 'running') {
        isAudioUnlocked = true;

        return;
    }

    if (context.state === 'suspended') {
        void context.resume().then(() => {
            if (context.state === 'running') {
                isAudioUnlocked = true;
            }
        });
    }
}

/**
 * Unlocks audio on the next user gesture anywhere in the document.
 *
 * @returns A cleanup that removes the listeners
 */
export function attachNotificationSoundUnlockListeners(): () => void {
    const currentWindow = browserWindow();

    if (!currentWindow || hasUnlockListeners) {
        return () => undefined;
    }

    hasUnlockListeners = true;

    const handleGesture = (): void => {
        unlockNotificationSound();
    };
    const gestureEvents = ['pointerdown', 'keydown', 'touchstart', 'click'];

    for (const eventName of gestureEvents) {
        currentWindow.document.addEventListener(eventName, handleGesture, {
            passive: true,
        });
    }

    return () => {
        for (const eventName of gestureEvents) {
            currentWindow.document.removeEventListener(
                eventName,
                handleGesture,
            );
        }

        hasUnlockListeners = false;
    };
}

/** Back to the defaults (sounds off, audio locked); for tests. */
export function resetNotificationSoundForTests(): void {
    preferences = { ...DEFAULT_PREFERENCES };
    isAudioUnlocked = false;
    hasUnlockListeners = false;

    if (audioContext) {
        void audioContext.close();
        audioContext = null;
    }
}

/** Simulates a successful unlock without Web Audio; for tests. */
export function markNotificationSoundUnlockedForTests(): void {
    isAudioUnlocked = true;
}

export function shouldPlayChatSound(): boolean {
    return preferences.isChatSoundEnabled && isVisibleTab() && isAudioUnlocked;
}

export function shouldPlayNotificationSound(): boolean {
    return (
        preferences.isNotificationSoundEnabled &&
        isVisibleTab() &&
        isAudioUnlocked
    );
}

/**
 * Chat: play when the unread total rises. The server does not count messages
 * for people already viewing the chat, so a rise means someone else wrote.
 */
export function shouldPlayChatSoundOnUnreadIncrease(
    previousUnreadCount: number,
    nextUnreadCount: number,
): boolean {
    return nextUnreadCount > previousUnreadCount && shouldPlayChatSound();
}

/**
 * Chat over realtime: a `playSound` flag on the event covers viewers (whose
 * unread count does not rise); the unread rise covers everyone else.
 */
export function shouldPlayChatSoundForUnreadEvent(
    previousUnreadCount: number,
    nextUnreadCount: number,
    shouldPlaySoundFlag?: boolean,
): boolean {
    return (
        (shouldPlaySoundFlag === true && shouldPlayChatSound()) ||
        shouldPlayChatSoundOnUnreadIncrease(
            previousUnreadCount,
            nextUnreadCount,
        )
    );
}

type SoundSequence = (context: AudioContext, startTime: number) => void;

/** A soft marimba-like pop: a short pitch dip with a filtered decay. */
function playPop(
    context: AudioContext,
    frequency: number,
    startTime: number,
    durationInSeconds: number,
    volume: number,
    options: { hasBody?: boolean } = {},
): void {
    const { hasBody = false } = options;
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    const filter = context.createBiquadFilter();
    const tailInSeconds = durationInSeconds + 0.04;

    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(hasBody ? 2800 : 2200, startTime);
    filter.frequency.exponentialRampToValueAtTime(
        700,
        startTime + durationInSeconds,
    );
    filter.Q.setValueAtTime(0.8, startTime);

    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(frequency * 1.05, startTime);
    oscillator.frequency.exponentialRampToValueAtTime(
        frequency,
        startTime + 0.022,
    );

    gain.gain.setValueAtTime(0, startTime);
    gain.gain.linearRampToValueAtTime(volume, startTime + 0.005);
    gain.gain.exponentialRampToValueAtTime(volume * 0.35, startTime + 0.028);
    gain.gain.exponentialRampToValueAtTime(
        0.001,
        startTime + durationInSeconds,
    );

    oscillator.connect(gain);
    gain.connect(filter);

    if (hasBody) {
        const harmonic = context.createOscillator();
        const harmonicGain = context.createGain();

        harmonic.type = 'triangle';
        harmonic.frequency.setValueAtTime(frequency * 2, startTime);
        harmonicGain.gain.setValueAtTime(0, startTime);
        harmonicGain.gain.linearRampToValueAtTime(
            volume * 0.18,
            startTime + 0.004,
        );
        harmonicGain.gain.exponentialRampToValueAtTime(
            0.001,
            startTime + durationInSeconds * 0.75,
        );

        harmonic.connect(harmonicGain);
        harmonicGain.connect(filter);

        harmonic.start(startTime);
        harmonic.stop(startTime + tailInSeconds);
    }

    filter.connect(context.destination);

    oscillator.start(startTime);
    oscillator.stop(startTime + tailInSeconds);
}

/** Chat: one light ding, shorter and softer than the notification chime. */
const chatSoundSequence: SoundSequence = (context, startTime) => {
    playPop(context, 987.77, startTime, 0.16, 0.09);
};

/** Notification: an ascending two-note chime (D5 then G5), about 280 ms. */
const notificationSoundSequence: SoundSequence = (context, startTime) => {
    playPop(context, 587.33, startTime, 0.13, 0.11, { hasBody: true });
    playPop(context, 783.99, startTime + 0.11, 0.15, 0.1, { hasBody: true });
};

/** Schedules a sequence, resuming the context if the browser suspended it. */
function playSoundSequence(sequence: SoundSequence): void {
    const context = ensureAudioContext();

    if (!context) {
        return;
    }

    const start = (): void => {
        if (context.state !== 'running') {
            return;
        }

        isAudioUnlocked = true;
        sequence(context, context.currentTime);
    };

    if (context.state === 'suspended') {
        void context.resume().then(start);

        return;
    }

    start();
}

export function playChatSound(): void {
    if (!shouldPlayChatSound()) {
        return;
    }

    playSoundSequence(chatSoundSequence);
}

export function playNotificationSound(): void {
    if (!shouldPlayNotificationSound()) {
        return;
    }

    playSoundSequence(notificationSoundSequence);
}

/**
 * Unlocks and plays from a click handler, ignoring the preferences and the tab
 * visibility: the "Test sound" button next to the preference.
 */
export function playTestSound(): void {
    unlockNotificationSound();
    playSoundSequence(notificationSoundSequence);
}
